  "Lagos": 1500, "Abuja": 2000, "FCT Abuja": 2000, "Rivers": 2500, "Kano": 3000,
  "Oyo": 2000, "Anambra": 2500, "Delta": 2500, "Edo": 2500, "Ogun": 1800,
